"use client";

import { useState, useMemo, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  CategorySlug,
  MOCK_PRODUCTS,
  CATEGORY_FILTERS,
  filterProducts,
  BRAND_LOGOS,
} from "@/data/store-data";
import { ChevronDown, SlidersHorizontal, X, ArrowUpDown, Layers } from "lucide-react";

const SORT_OPTIONS = [
  { label: "Newest Arrivals", value: "newest" },
  { label: "Price: Low to High", value: "price-asc" },
  { label: "Price: High to Low", value: "price-desc" },
];

function FilterSection({
  section,
  selectedOptions,
  onChange,
  isOpen,
  onToggle,
}: any) {
  const isBrandSection = section.id === "brand";
  const isPriceSection = section.id === "priceRange";
  const currentRange = isPriceSection
    ? (selectedOptions[0] || "0-10000").split("-")
    : [0, 10000];
  const maxVal = currentRange[1];

  return (
    <div className="border-b border-border py-5">
      <button
        onClick={onToggle}
        className="flex w-full items-center justify-between text-[11px] font-black text-foreground uppercase tracking-widest"
      >
        {section.label}
        <ChevronDown
          className={`w-4 h-4 transition-transform duration-300 ${
            isOpen ? "rotate-180" : ""
          }`}
        />
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="overflow-hidden"
          >
            <div className="pt-4 pb-2 space-y-3">
              {isPriceSection ? (
                <div className="px-2 pt-2 pb-6">
                  <div className="flex justify-between mb-4">
                    <span className="text-[10px] font-black uppercase text-foreground-subtle">
                      ₹0
                    </span>
                    <span className="text-xs font-black text-brand bg-brand/10 px-2 py-0.5 rounded">
                      Up to ₹{Number(maxVal).toLocaleString()}
                    </span>
                  </div>
                  <input
                    type="range"
                    min="0"
                    max="10000"
                    step="500"
                    value={maxVal}
                    onChange={(e) => onChange(`0-${e.target.value}`, true)}
                    className="w-full h-1.5 bg-background-muted rounded-lg appearance-none cursor-pointer accent-brand"
                    style={{
                      background: `linear-gradient(to right, var(--brand-primary) 0%, var(--brand-primary) ${
                        Number(maxVal) / 100
                      }%, var(--surface-muted) ${
                        Number(maxVal) / 100
                      }%, var(--surface-muted) 100%)`,
                    }}
                  />
                </div>
              ) : (
                section.options.map((option: string) => {
                  const isChecked = selectedOptions.includes(option);
                  const logo = BRAND_LOGOS[option];
                  return (
                    <label
                      key={option}
                      className="flex items-center group cursor-pointer w-full"
                    >
                      <div
                        className={`h-4 w-4 shrink-0 border-2 rounded-sm flex items-center justify-center transition-all ${
                          isChecked
                            ? "bg-brand border-brand"
                            : "border-border bg-background-muted"
                        }`}
                      >
                        {isChecked && (
                          <div className="w-1.5 h-1.5 bg-brand-foreground rounded-full" />
                        )}
                      </div>
                      <input
                        type="checkbox"
                        className="hidden"
                        checked={isChecked}
                        onChange={() => onChange(option, false)}
                      />
                      <div className="ml-3 flex items-center gap-3 w-full">
                        {isBrandSection && logo && (
                          <img
                            src={logo}
                            alt=""
                            className="h-5 w-8 object-contain dark:invert opacity-80"
                          />
                        )}
                        <span
                          className={`text-xs uppercase tracking-tight ${
                            isChecked
                              ? "text-foreground font-black"
                              : "text-foreground-subtle"
                          }`}
                        >
                          {option}
                        </span>
                      </div>
                    </label>
                  );
                })
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default function CategoryClient({
  category,
}: {
  category: CategorySlug;
}) {
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const [openSectionId, setOpenSectionId] = useState<string | null>(null);
  const [activeFilters, setActiveFilters] = useState<Record<string, string[]>>({
    priceRange: ["0-10000"],
  });
  const [sortBy, setSortBy] = useState("newest");

  // --- SCROLL LOCK LOGIC ---
  useEffect(() => {
    if (isFilterOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isFilterOpen]);

  const products = useMemo(
    () => MOCK_PRODUCTS.filter((p) => p.category === category),
    [category]
  );
  const availableFilters = CATEGORY_FILTERS[category] || [];

  const allFilters = useMemo(
    () => [
      { id: "priceRange", label: "Price Range", options: [] },
      ...availableFilters,
    ],
    [availableFilters]
  );

  const filteredAndSortedProducts = useMemo(() => {
    let result = filterProducts(products, activeFilters);
    if (sortBy === "price-asc") result.sort((a, b) => a.price - b.price);
    if (sortBy === "price-desc") result.sort((a, b) => b.price - a.price);
    return result;
  }, [products, activeFilters, sortBy]);

  const handleFilterChange = (
    filterId: string,
    option: string,
    isRange: boolean
  ) => {
    setActiveFilters((prev) => {
      const current = prev[filterId] || [];
      if (isRange) return { ...prev, [filterId]: [option] };
      return current.includes(option)
        ? { ...prev, [filterId]: current.filter((o) => o !== option) }
        : { ...prev, [filterId]: [...current, option] };
    });
  };

  return (
    <div className="bg-background min-h-screen text-foreground transition-colors duration-500">
      {/* HEADER */}
      <div className="sticky top-16 z-30 bg-background backdrop-blur-md border-border">
        <div className="max-w-7xl mx-auto flex px-2">
          {/* Category */}
         

          {/* Filter */}
          <button
            
            className="flex-1 flex items-center justify-center gap-2 text-[11px] font-black uppercase border border-border py-2 hover:bg-muted transition"
          >
            <SlidersHorizontal size={14} />
            Filter
          </button>

          {/* Sort */}
          <button
            
            className="flex-1 flex items-center justify-center gap-2 text-[11px] font-black uppercase border border-border py-2 hover:bg-muted transition"
          >
            <ArrowUpDown size={14} />
            Sort
          </button>
        
        </div>
      </div>

      {/* GRID */}
      <main className="max-w-7xl mx-auto px-4 py-8 mb-24">
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-x-4 gap-y-10">
          {filteredAndSortedProducts.map((product) => (
            <motion.div layout key={product.id} className="group">
              <div className="aspect-4/5 overflow-hidden rounded-4xl bg-background-muted border border-border/50">
                <img
                  src={product.image}
                  alt=""
                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                />
              </div>
              <div className="mt-4 px-1 space-y-1">
                <p className="text-[9px] font-black text-foreground-subtle uppercase">
                  {product.brand}
                </p>
                <h2 className="text-xs font-bold uppercase truncate">
                  {product.name}
                </h2>
                <p className="text-sm font-black">
                  ₹{product.price.toLocaleString()}
                </p>
              </div>
            </motion.div>
          ))}
        </div>
      </main>

      {/* DRAWER */}
      <AnimatePresence>
        {isFilterOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsFilterOpen(false)}
              className="fixed inset-0 z-[60] bg-background/60 backdrop-blur-sm"
            />
            <motion.div
              initial={{ y: "100%" }}
              animate={{ y: 0 }}
              exit={{ y: "100%" }}
              drag="y"
              dragConstraints={{ top: 0 }}
              onDragEnd={(_, info) => {
                if (info.offset.y > 100) setIsFilterOpen(false);
              }}
              className="fixed bottom-0 left-0 right-0 z-[70] bg-background-elevated border-t border-border rounded-t-[2.5rem] max-h-[85vh] flex flex-col shadow-2xl"
            >
              <div className="w-full flex justify-center py-4 cursor-grab">
                <div className="w-10 h-1 bg-border rounded-full" />
              </div>
              <div className="px-6 pb-8 pt-2 overflow-y-auto no-scrollbar">
                <div className="flex justify-between items-center mb-6">
                  <h3 className="text-xl font-black uppercase italic">
                    Refine
                  </h3>
                  <button
                    onClick={() => setIsFilterOpen(false)}
                    className="p-2 bg-background-muted rounded-full"
                  >
                    <X size={20} />
                  </button>
                </div>

                {/* SORTING SECTION */}
                <div className="border-b border-border py-5">
                  <span className="text-[10px] font-black uppercase text-foreground-subtle tracking-widest mb-4 block">
                    Sort By
                  </span>
                  <div className="flex flex-wrap gap-2">
                    {SORT_OPTIONS.map((opt) => (
                      <button
                        key={opt.value}
                        onClick={() => setSortBy(opt.value)}
                        className={`px-4 py-2 rounded-full text-[10px] font-bold uppercase transition-all ${
                          sortBy === opt.value
                            ? "bg-brand text-brand-foreground"
                            : "bg-background-muted text-foreground-subtle"
                        }`}
                      >
                        {opt.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* FILTER SECTIONS (Exclusive Accordion) */}
                <div className="space-y-1">
                  {allFilters.map((section) => (
                    <FilterSection
                      key={section.id}
                      section={section}
                      isOpen={openSectionId === section.id}
                      onToggle={() =>
                        setOpenSectionId(
                          openSectionId === section.id
                            ? null
                            : (section.id as string)
                        )
                      }
                      selectedOptions={activeFilters[section.id] || []}
                      onChange={(opt: string, isRange: boolean) =>
                        handleFilterChange(section.id as string, opt, isRange)
                      }
                    />
                  ))}
                </div>

                <div className="mt-8 grid grid-cols-2 gap-4 sticky bottom-0 bg-background-elevated pt-4 border-t border-border/10">
                  <button
                    onClick={() => {
                      setActiveFilters({ priceRange: ["0-10000"] });
                      setSortBy("newest");
                      setOpenSectionId(null);
                    }}
                    className="py-4 text-[10px] font-black uppercase tracking-widest text-foreground-subtle"
                  >
                    Reset
                  </button>
                  <button
                    onClick={() => setIsFilterOpen(false)}
                    className="py-4 bg-brand text-brand-foreground rounded-full text-[10px] font-black uppercase tracking-widest"
                  >
                    Done
                  </button>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      <style jsx>{`
        input[type="range"]::-webkit-slider-thumb {
          appearance: none;
          height: 18px;
          width: 18px;
          border-radius: 50%;
          background: var(--brand-foreground);
          border: 3px solid var(--brand-primary);
          cursor: pointer;
          box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
        }
      `}</style>
    </div>
  );
}
